import javax.crypto.SecretKey;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.DESKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.security.spec.InvalidKeySpecException;
import java.util.Arrays;

public static SecretKey generateDesKey(String seed) throws NoSuchAlgorithmException, InvalidKeySpecException {
    if (seed == null) {
        throw new IllegalArgumentException("Seed must not be null");
    }

    MessageDigest sha256 = MessageDigest.getInstance("SHA-256");
    byte[] hash = sha256.digest(seed.getBytes(StandardCharsets.UTF_8));

    // DES requires 8 bytes (64 bits, of which 56 are key bits and 8 are parity bits)
    byte[] keyBytes = Arrays.copyOf(hash, 8);

    // Set each byte's least significant bit so that every byte has odd parity
    for (int i = 0; i < keyBytes.length; i++) {
        int bitsWithoutParity = keyBytes[i] & 0xFE;
        int parityBit = (Integer.bitCount(bitsWithoutParity) % 2 == 0) ? 1 : 0;
        keyBytes[i] = (byte) (bitsWithoutParity | parityBit);
    }

    DESKeySpec desKeySpec = new DESKeySpec(keyBytes);
    SecretKeyFactory keyFactory = SecretKeyFactory.getInstance("DES");
    return keyFactory.generateSecret(desKeySpec);
}
