import javax.crypto.SecretKey;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.DESKeySpec;
import javax.crypto.spec.PBEKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.GeneralSecurityException;
import java.security.MessageDigest;

public class DesKeyGenerator {

    private static final int PBKDF2_ITERATIONS = 210_000;
    private static final int DES_KEY_BYTES = 8;

    /**
     * Deterministically derives a DES key from the given seed string.
     * Note: DES is obsolete (56-bit effective key); prefer AES for new systems.
     */
    public static SecretKey generateDesKey(String seed) throws GeneralSecurityException {
        if (seed == null || seed.isEmpty()) {
            throw new IllegalArgumentException("Seed must not be null or empty");
        }

        // Derive a salt from the seed so the output is deterministic for the same seed
        MessageDigest sha256 = MessageDigest.getInstance("SHA-256");
        byte[] salt = sha256.digest(("DES-KEY-SALT:" + seed).getBytes(StandardCharsets.UTF_8));

        PBEKeySpec pbeSpec = new PBEKeySpec(
                seed.toCharArray(),
                salt,
                PBKDF2_ITERATIONS,
                DES_KEY_BYTES * 8);

        byte[] keyBytes;
        try {
            SecretKeyFactory pbkdf2 = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
            keyBytes = pbkdf2.generateSecret(pbeSpec).getEncoded();
        } finally {
            pbeSpec.clearPassword();
        }

        DESKeySpec desKeySpec = new DESKeySpec(keyBytes);
        SecretKeyFactory desFactory = SecretKeyFactory.getInstance("DES");
        return desFactory.generateSecret(desKeySpec);
    }
}
