    }
    if salt.len() < 8 {
        return Err(HashError::InvalidSalt("salt must be at least 8 bytes long"));
    }
    if !salt.bytes().all(|b| b.is_ascii_alphanumeric()) {
        return Err(HashError::InvalidSalt("salt must contain only ASCII alphanumeric characters"));
