use crypto::hmac::Hmac;
use crypto::pbkdf2::pbkdf2;
use crypto::sha1::Sha1;

// Note: the spec asks for PBKDF2 with HMAC-SHA1, so the HMAC is built on `Sha1`.
// `Md5` (crypto::md5::Md5) could be swapped in as the digest, but MD5 is not
// recommended for password hashing.

const MIN_SALT_LEN: usize = 8;
const MAX_SALT_LEN: usize = 128;
const ITERATIONS: u32 = 100_000;
const OUTPUT_LEN: usize = 20; // SHA-1 output size

#[derive(Debug)]
pub enum HashError {
    EmptyPassword,
    SaltTooShort,
    SaltTooLong,
}

impl std::fmt::Display for HashError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            HashError::EmptyPassword => write!(f, "password must not be empty"),
            HashError::SaltTooShort => {
                write!(f, "salt must be at least {} bytes long", MIN_SALT_LEN)
            }
            HashError::SaltTooLong => {
                write!(f, "salt must be at most {} bytes long", MAX_SALT_LEN)
            }
        }
    }
}

impl std::error::Error for HashError {}

fn validate_salt(salt: &[u8]) -> Result<(), HashError> {
    if salt.len() < MIN_SALT_LEN {
        return Err(HashError::SaltTooShort);
    }
    if salt.len() > MAX_SALT_LEN {
        return Err(HashError::SaltTooLong);
    }
    Ok(())
}

pub fn hash_password(password: &str, salt: &[u8]) -> Result<String, HashError> {
    if password.is_empty() {
        return Err(HashError::EmptyPassword);
    }
    validate_salt(salt)?;

    let mut mac = Hmac::new(Sha1::new(), password.as_bytes());
    let mut output = [0u8; OUTPUT_LEN];
    pbkdf2(&mut mac, salt, ITERATIONS, &mut output);

    let hex: String = output.iter().map(|b| format!("{:02x}", b)).collect();
    Ok(hex)
}

