    match hash_password("my_secret_password", b"random_salt_value") {
        Ok(hash) => println!("Hashed password: {}", hash),
        Err(e) => eprintln!("Error: {}", e),
    }

    match hash_password("my_secret_password", b"short") {
        Ok(hash) => println!("Hashed password: {}", hash),
        Err(e) => eprintln!("Error: {}", e),
    }
}
