{
    $body = '';

    foreach ($fields as $name => $value) {
        $safeName = addcslashes((string)$name, "\"\\");
        $body .= "--{$boundary}\r\n";
        $body .= "Content-Disposition: form-data; name=\"{$safeName}\"\r\n\r\n";
        $body .= (string)$value . "\r\n";
    }

    $body .= "--{$boundary}--\r\n";

    $offset = 0;

    return function (int $length) use (&$body, &$offset): string {
        if ($length < 0) {
            throw new InvalidArgumentException('Chunk length must be non-negative.');
        }

        $chunk = substr($body, $offset, $length);

        if ($chunk === false) {
            return '';
        }

        $offset += strlen($chunk);

        return $chunk;
