<?php

/**
 * Generates a multipart boundary using a hash function and streams
 * the request body in fixed-size chunks.
 */
class MultipartBodyStream
{
    private string $boundary;
    private string $body;
    private int $offset = 0;
    private int $length;

    /**
     * @param array $fields Associative array of name => value
     * @param array $files  Associative array of name => ['filename' => ..., 'content' => ..., 'type' => ...]
     */
    public function __construct(array $fields = [], array $files = [])
    {
        $this->boundary = self::generateBoundary();
        $this->body     = $this->buildBody($fields, $files);
        $this->length   = strlen($this->body);
    }

    public static function generateBoundary(): string
    {
        $entropy = random_bytes(16) . microtime(true) . uniqid('', true);
        return '----Boundary' . substr(hash('sha256', $entropy), 0, 32);
    }

    public function getBoundary(): string
    {
        return $this->boundary;
    }

    public function getContentType(): string
    {
        return 'multipart/form-data; boundary=' . $this->boundary;
    }

    public function getContentLength(): int
    {
        return $this->length;
    }

    /**
     * Returns the next chunk of the body of up to $chunkLength bytes.
     * Returns an empty string when the body is exhausted.
     */
    public function getNextChunk(int $chunkLength): string
    {
        if ($chunkLength <= 0) {
            throw new InvalidArgumentException('Chunk length must be greater than zero.');
        }

        if ($this->offset >= $this->length) {
            return '';
        }

        $chunk = substr($this->body, $this->offset, $chunkLength);
        $this->offset += strlen($chunk);

        return $chunk;
    }

    public function isFinished(): bool
    {
        return $this->offset >= $this->length;
    }

    public function reset(): void
    {
        $this->offset = 0;
    }

    private function buildBody(array $fields, array $files): string
    {
        $eol  = "\r\n";
        $body = '';

        foreach ($fields as $name => $value) {
            $body .= '--' . $this->boundary . $eol;
            $body .= 'Content-Disposition: form-data; name="' . addcslashes((string)$name, "\"\\") . '"' . $eol . $eol;
            $body .= $value . $eol;
        }

        foreach ($files as $name => $file) {
            $filename = $file['filename'] ?? 'file';
            $type     = $file['type'] ?? 'application/octet-stream';
            $content  = $file['content'] ?? '';

            $body .= '--' . $this->boundary . $eol;
            $body .= 'Content-Disposition: form-data; name="' . addcslashes((string)$name, "\"\\")
                   . '"; filename="' . addcslashes($filename, "\"\\") . '"' . $eol;
            $body .= 'Content-Type: ' . $type . $eol . $eol;
            $body .= $content . $eol;
        }

        $body .= '--' . $this->boundary . '--' . $eol;

        return $body;
    }
}

// Example usage:
// $stream = new MultipartBodyStream(
//     ['username' => 'alice'],
//     ['avatar' => ['filename' => 'a.txt', 'content' => 'Hello', 'type' => 'text/plain']]
// );
