char *format_signed_int(const char *s)
{
    size_t len = strlen(s);
    int neg = (s[0] == '-');
    int has_explicit = (s[0] == '-' || s[0] == '+');
    const char *digits = has_explicit ? s + 1 : s;
    size_t nd = strlen(digits);

    size_t target = (len <= 3) ? len + 3 : len;
    int has_sign = neg || (len <= 3);
    char sign = neg ? '-' : ' ';
    size_t slen = has_sign ? 1 : 0;

    size_t zeros = 0;
    if (target >= slen + nd)
        zeros = target - slen - nd;

    char *out = malloc(target + 1);
    if (!out)
        return NULL;

    size_t pos = 0;
    if (has_sign)
        out[pos++] = sign;
    memset(out + pos, '0', zeros);
    pos += zeros;
    memcpy(out + pos, digits, nd);
    pos += nd;
    out[pos] = '\0';

    return out;
}
