char *pad_signed_integer(const char *input)
{
    if (input == NULL || *input == '\0')
        return NULL;

    size_t len = strlen(input);
    size_t target = (len >= 1 && len <= 3) ? len + 3 : len;

    const char *digits = input;
    char sign = 0;

    if (*digits == '-') {
        sign = '-';
        digits++;
    } else if (*digits == '+') {
        sign = ' ';   /* optional space in place of an explicit plus */
        digits++;
    }

    size_t ndigits = strlen(digits);
    size_t sign_len = sign ? 1 : 0;

    if (target < sign_len + ndigits)
        target = sign_len + ndigits;

    char *out = (char *)malloc(target + 1);
    if (out == NULL)
        return NULL;

    size_t pos = 0;
    if (sign)
        out[pos++] = sign;

    size_t zeros = target - sign_len - ndigits;
    memset(out + pos, '0', zeros);
    pos += zeros;

    memcpy(out + pos, digits, ndigits);
    pos += ndigits;

    out[pos] = '\0';
    return out;
}
