#include <stdbool.h>
#include <stddef.h>
#include <string.h>
#include <limits.h>
#include <openssl/evp.h>
#include <openssl/crypto.h>

#define AES_256_KEY_LEN 32
#define AES_CBC_IV_LEN  16
#define MIN_ITERATIONS  10000

/*
 * Derives a 256-bit key and 128-bit IV for AES-256-CBC using
 * PBKDF2-HMAC-SHA256.
 *
 * password     : password bytes (may not be NULL)
 * password_len : length of password in bytes
 * salt         : salt bytes (may not be NULL, recommended >= 16 bytes)
 * salt_len     : length of salt in bytes
 * iterations   : PBKDF2 iteration count (must be >= MIN_ITERATIONS)
 * key_out      : buffer of at least 32 bytes
 * iv_out       : buffer of at least 16 bytes
 *
 * Returns true on success, false on failure. On failure, outputs are zeroed.
 */
bool derive_key_and_iv(const char *password, size_t password_len,
                       const unsigned char *salt, size_t salt_len,
                       unsigned int iterations,
                       unsigned char key_out[AES_256_KEY_LEN],
                       unsigned char iv_out[AES_CBC_IV_LEN])
{
    unsigned char derived[AES_256_KEY_LEN + AES_CBC_IV_LEN];
    bool ok = false;

    if (password == NULL || salt == NULL || key_out == NULL || iv_out == NULL)
        return false;
    if (salt_len == 0 || iterations < MIN_ITERATIONS)
        return false;
    if (password_len > INT_MAX || salt_len > INT_MAX || iterations > INT_MAX)
        return false;

    if (PKCS5_PBKDF2_HMAC(password, (int)password_len,
                          salt, (int)salt_len,
                          (int)iterations,
                          EVP_sha256(),
                          (int)sizeof(derived), derived) != 1) {
        goto cleanup;
    }

    memcpy(key_out, derived, AES_256_KEY_LEN);
    memcpy(iv_out, derived + AES_256_KEY_LEN, AES_CBC_IV_LEN);
    ok = true;

cleanup:
    OPENSSL_cleanse(derived, sizeof(derived));
    if (!ok) {
        OPENSSL_cleanse(key_out, AES_256_KEY_LEN);
        OPENSSL_cleanse(iv_out, AES_CBC_IV_LEN);
    }
    return ok;
}
