function createParticleSystem(m) {
  const width = 900;
  const height = 300;

  // Visible canvas
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  canvas.style.background = '#000';
  canvas.style.cursor = 'pointer';
  document.body.appendChild(canvas);
  const ctx = canvas.getContext('2d');

  // Offscreen canvas used to create the bitmap of the message
  const offscreen = document.createElement('canvas');
  offscreen.width = width;
  offscreen.height = height;
  const octx = offscreen.getContext('2d');
  octx.fillStyle = '#fff';
  octx.font = 'bold 120px Arial';
  octx.textAlign = 'center';
  octx.textBaseline = 'middle';
  octx.fillText(m, width / 2, height / 2);

  // Sample the bitmap to build the particle system
  const imageData = octx.getImageData(0, 0, width, height).data;
  const gap = 4;
  const particles = [];

  for (let y = 0; y < height; y += gap) {
    for (let x = 0; x < width; x += gap) {
      const alpha = imageData[(y * width + x) * 4 + 3];
      if (alpha > 128) {
        const hue = (x / width) * 360;
        particles.push({
          homeX: x,
          homeY: y,
          x: x,
          y: y,
          vx: 0,
          vy: 0,
          alpha: 1,
          color: `hsl(${hue}, 100%, 60%)`,
          exploded: false
        });
      }
    }
  }

  let exploding = false;

  // Randomly assigns velocities to each particle
  function explode() {
    exploding = true;
    particles.forEach(p => {
      const angle = Math.random() * Math.PI * 2;
      const speed = Math.random() * 12 + 2;
      p.vx = Math.cos(angle) * speed;
      p.vy = Math.sin(angle) * speed;
      p.exploded = true;
      p.alpha = 1;
    });
  }

  // Pulls particles back to their original positions
  function reset() {
    exploding = false;
    particles.forEach(p => {
      p.exploded = false;
      p.alpha = 1;
    });
  }

  function update() {
    particles.forEach(p => {
      if (p.exploded) {
        p.vy += 0.15;          // gravity
        p.vx *= 0.99;          // air friction
        p.vy *= 0.99;
        p.x += p.vx;
        p.y += p.vy;
        p.alpha -= 0.004;
        if (p.alpha < 0) p.alpha = 0;
      } else {
        const ax = (p.homeX - p.x) * 0.05;
        const ay = (p.homeY - p.y) * 0.05;
        p.vx = (p.vx + ax) * 0.85;
        p.vy = (p.vy + ay) * 0.85;
        p.x += p.vx;
        p.y += p.vy;
        p.alpha = Math.min(1, p.alpha + 0.05);
      }
    });
  }

  function draw() {
    ctx.clearRect(0, 0, width, height);
    particles.forEach(p => {
      if (p.alpha <= 0) return;
      ctx.globalAlpha = p.alpha;
      ctx.fillStyle = p.color;
      ctx.fillRect(p.x, p.y, 3, 3);
    });
    ctx.globalAlpha = 1;
  }

  function animate() {
    update();
    draw();
    requestAnimationFrame(animate);
  }

  canvas.addEventListener('click', () => {
    if (exploding) {
      reset();
    } else {
      explode();
    }
  });

  animate();

  return { explode, reset, particles };
}
