/**
 * Swaps two elements in an array in place.
 * @param {Array} arr - The array containing the elements.
 * @param {number} i - Index of the first element.
 * @param {number} j - Index of the second element.
 * @returns {Array} The same array with the elements swapped.
 */
function swap(arr, i, j) {
  if (
    !Array.isArray(arr) ||
    !Number.isInteger(i) ||
    !Number.isInteger(j) ||
    i < 0 || j < 0 ||
    i >= arr.length || j >= arr.length
  ) {
    throw new RangeError("Invalid array or indices for swap.");
  }
  [arr[i], arr[j]] = [arr[j], arr[i]];
  return arr;
}

/**
 * Returns a new array shuffled using the Fisher-Yates algorithm.
 * @param {Array} array - The input array (not modified).
 * @param {number} [times=1] - Number of times to shuffle the array.
 * @returns {Array} A new shuffled array.
 */
function fisherYatesShuffle(array, times = 1) {
  if (!Array.isArray(array)) {
    throw new TypeError("Input must be an array.");
  }
  if (!Number.isInteger(times) || times < 1) {
    throw new RangeError("Number of shuffles must be a positive integer.");
  }

  const result = array.slice();

  for (let t = 0; t < times; t++) {
    for (let i = result.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      swap(result, i, j);
    }
  }

  return result;
}

