}

// Scan /proc for processes whose cwd or open fds are inside 'dir'.
static std::vector<pid_t> findOffendingProcesses(const std::string& dir) {
    std::vector<pid_t> result;
    const pid_t self = getpid();
    const pid_t parent = getppid();

    std::error_code ec;
    for (const auto& entry : fs::directory_iterator("/proc", ec)) {
        const std::string name = entry.path().filename().string();
        if (!isDigits(name)) continue;

        pid_t pid = static_cast<pid_t>(std::stoi(name));
        if (pid == self || pid == parent || pid <= 1) continue;

        bool match = isInside(readLink(entry.path() / "cwd"), dir);

        if (!match) {
            std::error_code fdEc;
            for (const auto& fd : fs::directory_iterator(entry.path() / "fd", fdEc)) {
                if (isInside(readLink(fd.path()), dir)) {
                    match = true;
                    break;
                }
            }
        }
        if (match) result.push_back(pid);
    }
    return result;
